-- Backfill: the last approved PO behind each material, as IN4 held it on
-- 12 Sep 2026 — 2,446 materials out of 4,041.
--
-- Without this the Item Master would show nothing under "last bought" until the
-- next masters sync at 09:00 IST. The sync keeps it current from then on; this
-- is only so the screen is complete the moment it deploys.
--
-- Idempotent: re-running it restores this snapshot, and the next sync overwrites
-- it with whatever IN4 says then.
on conflict (material_id) do update set po_id=excluded.po_id, po_no=excluded.po_no, po_dt=excluded.po_dt, supplier_id=excluded.supplier_id, rate=excluded.rate, qty=excluded.qty, project_id=excluded.project_id, subproject_id=excluded.subproject_id, synced_at=now();

